<template>
<k-feature-gate feature="wish"><view class="wish-page">
  <template v-if="wish"><view class="wd-hero"><swiper v-if="wish.images.length" class="wd-photos" :indicator-dots="wish.images.length>1" indicator-active-color="#e7f58a"><swiper-item v-for="src in wish.images" :key="src"><image :src="absUrl(src)" mode="aspectFill" @click="preview(src)"/></swiper-item></swiper><view v-else class="wd-photos w-empty-cover"><k-icon name="heart-handshake" :size="90" color="#537d99"/></view><view class="wd-top"><k-topbar back dark bg="transparent" :fab="false"/></view><text class="wd-location">{{wish.targetCity}} · {{categoryText(wish.category)}}</text></view>
    <view class="wd-main"><view class="w-between"><text class="w-tag" :class="{'w-tag--lime':wish.mode==='free'}">{{wish.mode==='free'?'免费互助':'有偿互助'}}</text><text class="w-muted">{{statusText(wish.status)}}</text></view><text class="w-title wd-title">{{wish.title}}</text><view class="w-row"><text class="w-price">¥{{money(wish.amountFen)}}</text><text class="w-muted">{{wish.mode==='free'?'善意同行，全程不收费':'已含 1% 加价'}}</text></view><view class="w-rule"/><view class="w-row"><image v-if="wish.publisherAvatar" class="w-avatar" :src="absUrl(wish.publisherAvatar)"/><view v-else class="w-avatar w-avatar--fallback">{{wish.publisherName?.slice(0,1)||'愿'}}</view><text>{{wish.publisherName||'心愿发布者'}}</text><text class="w-muted">· {{wish.originCity}}</text></view><view class="w-route w-section"><view class="w-row"><k-icon name="map-pin" :size="17" color="#102c46"/><text>{{wish.targetCity}}</text></view><k-icon name="arrow-right" :size="22" color="#8a9db4"/><text>{{wish.originCity}}</text></view><text class="w-copy wd-copy">{{wish.description}}</text><view class="w-row wd-meta"><k-icon name="calendar-days" :size="17" color="#6e8197"/><text>{{String(wish.deadline).slice(0,10)}} 前完成</text><text>· {{deliveryText(wish.delivery)}}</text></view><w-fees :value="wish" :free="wish.mode==='free'"/><view v-if="wish.requiredTypes?.some(t=>t!=='ordinary')" class="w-tip w-section"><k-icon name="shield-check" :size="18" color="#3166f5"/><view>实际内容涉及 {{(wish.requiredTypes||[]).filter(t=>t!=='ordinary').map(t=>({food:'食品',tobacco:'烟草',alcohol:'酒类'})[t]).join('、')||'受限品类'}}，服务者须持有效资质及对应城市许可。<text class="w-blue" @click="go(route('credential'))">前往提交资质 →</text></view></view><text v-if="wish.informationOnly" class="w-caption w-section">平台已核实为线上信息咨询，普通用户可参与，无需食品经营资质。</text><text v-else class="w-caption w-section">普通用户也可参与互助。资质仅按实际服务内容核验；如果只是问答却被要求食品资质，请联系平台复核分类。</text><view class="w-field" @click="go(route('rules'))"><k-icon name="shield-check" :size="18" color="#102c46"/><text class="w-grow">互助规则与费用说明</text><k-icon name="chevron-right" :size="18" color="#718095"/></view></view>
    <view class="w-bottom"><button v-if="wish.isOwner||wish.isHelper" class="w-primary" @click="go(route('order',id))">查看我的订单<k-icon name="arrow-right" :size="22" color="#e7f58a"/></button><button v-else class="w-primary w-primary--lime" :disabled="wish.status!=='open'" @click="acceptOpen=true">我来帮忙<k-icon name="arrow-up-right" :size="23" color="#102c46"/></button></view>
    <view v-if="acceptOpen" class="w-mask" @click="acceptOpen=false"><view class="w-sheet" @click.stop><view class="w-between"><text class="w-heading">让这个心愿，向前一步</text><button class="w-link" @click="acceptOpen=false">关闭</button></view><text class="w-caption">接单后可在订单内与发布者沟通。请先确认城市、交付方式和时间。</text><view class="w-card w-section"><text class="w-heading">{{wish.title}}</text><text class="w-caption">{{wish.targetCity}} → {{wish.originCity}}</text><text class="w-caption">{{String(wish.deadline).slice(0,10)}} · {{deliveryText(wish.delivery)}}</text></view><w-fees :value="wish" :free="wish.mode==='free'"/><view class="w-check" @click="agreed=!agreed"><view class="w-check__box" :class="{on:agreed}"><k-icon v-if="agreed" name="check" :size="15" color="white"/></view><text>我已了解费用与交付要求，具备完成此心愿的能力。</text></view><button class="w-primary w-primary--lime" :disabled="busy||!agreed" @click="accept">{{busy?'正在确认…':'确认接单'}}</button></view></view>
  </template><template v-else><k-topbar title="心愿详情" back :fab="false"/><view class="w-state"><text>{{error||'正在加载心愿…'}}</text><button v-if="error" class="w-secondary" @click="load">重试</button></view></template>
</view></k-feature-gate>
</template>
<script setup>
import { publicShare, shareWithCover, timelineShare, showPublicShareMenu } from '@/common/public-share.js'
import { ref } from 'vue'
import { onLoad, onShow, onShareAppMessage, onShareTimeline } from '@dcloudio/uni-app'
import { wishDetail,wishAccept } from '@/common/wish-api.js'
import { absUrl } from '@/common/upload.js'
import { go,replace,toast } from '@/common/screen.js'
import { route,money,categoryText,deliveryText,statusText } from './wish.js'
import WFees from './components/w-fees.vue'
const id=ref(0),wish=ref(null),error=ref(''),acceptOpen=ref(false),agreed=ref(false),busy=ref(false)
async function load(){if(!id.value)return;try{error.value='';wish.value=(await wishDetail(id.value)).data}catch(e){wish.value=null;error.value=e.message||'无法加载心愿'}}
async function accept(){if(busy.value||!agreed.value)return;busy.value=true;try{await wishAccept(id.value);replace(route('order',id.value))}catch(e){toast(e.message||'接单失败');await load()}finally{busy.value=false}}
function preview(src){uni.previewImage({current:absUrl(src),urls:wish.value.images.map(absUrl)})}
onLoad(q=>{id.value=Number(q.id)});onShow(load);const pageShareMessage = ()=>({title:wish.value?.title||'心愿互助',path:route('detail',id.value)})

onShareAppMessage((event) => shareWithCover(pageShareMessage(event)))
onShareTimeline(() => timelineShare(pageShareMessage()))
onShow(showPublicShareMenu)
</script>
<style lang="scss">@import './wish.scss';.wd-hero{position:relative;height:340px;background:#102c46}.wd-photos{width:100%;height:100%}.wd-photos image{width:100%;height:100%}.wd-top{position:absolute;top:0;left:0;right:0;background:linear-gradient(#102c467a,transparent);color:white}.wd-location{position:absolute;bottom:35px;left:20px;background:#102c46a6;color:white;border-radius:8px;padding:6px 12px;font-size:11px;backdrop-filter:blur(8px)}.wd-main{position:relative;margin-top:-20px;background:white;border-radius:24px 24px 0 0;padding:23px 22px 10px}.wd-title{margin:17px 0 12px;font-size:25px}.wd-copy{display:block;margin:22px 0}.wd-meta{font-size:11px;color:#63768c;margin-bottom:24px;gap:7px}
</style>
